<% if @quizzes.empty? %>
  <p class="empty">No quizzes yet. Create a quiz to get started.</p>
<% else %>
  <ul class="quiz-list clean-list">
    <% @quizzes.each do |quiz| %>
      <li><%= link_to [:moderate, quiz], class: "card quiz-tile" do %>
        <h3><%= quiz.title %></h3><span class="meta"><%= pluralize(@counts.fetch(quiz.id, 0), "question") %></span>
      <% end %></li>
    <% end %>
  </ul>
<% end %>
